/**
 * The demotion provenance appended to an INLINE body. File-referenced
 * findings get the note appended to their comment file by the runner (file
 * writes stay out of this module).
 */
function stampDemotionBody(entry, note) {
    if (typeof entry.body === 'string' && entry.body.trim()) {
        entry.body = entry.body.replace(/\s*$/, '') + '\n' + note;
    }
}

/**
 * The keep outcome: the finding posts unchanged.
 */
function applyKeepVerdict(v, applied) {
726:function resolveInlineComment(inlineComment, ticketKey, workingDir) {
756:    var commentText = machineStampedInlineText(inlineComment, resolveInlineComment(inlineComment, ticketKey, workingDir));
1164:        return resolveInlineComment(inlineComment, ctx.ticketKey, ctx.workingDir);
 * ("+Subproject commit ..."), i.e. the submodule was updated rather than deleted.
 */
function submoduleHasNewPointer(diffText, filePath) {
    if (!diffText || !filePath) return false;
    return scanSubmoduleSegment(diffText, filePath, startsWithNewSubprojectCommit);
}

function postFallbackInlineComment(scm, pullRequestId, filePath, line, commentText) {
